public Yaf_Request_AbstractnullYaf_Request_Abstract::setActionName stringaction boolformat_nametrue
Establecer el nombre de la acción a solicitar, esto es usualmente usado por el enrutador personalizado para establecer el nombre del controlador de resultado de ruta.

&reftitle.returnvalues;

 Devuelve el propio objeto de la petición en caso de éxito, o &null; en caso
 de error.

  &reftitle.examples;

   Ejemplo de Yaf_Request_Abstract::setActionName


<?php
class RestRouter extends Yaf_Route_Interface
{
    public function route(Yaf_Request_Abstract $request)
    {
        // Enruta cualquier petición /api hacia ApiController::ordersAction
        if (0 === strpos($request->getRequestUri(), "/api")) {
            $request->setControllerName("Api")
                    ->setActionName("orders");
            return true;
        }

        return false;
    }

    public function assemble(array $info, array $query = null) {}
}
?>
